import React from "react";
import {
  FaCode,
  FaAward,
  FaLaptopCode,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaExternalLinkAlt
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* BACKGROUND */}
      <div className="glow"></div>

      {/* PARTICLES */}
      <div className="particles">
        {Array.from({ length: 40 }).map((_, i) => (
          <span key={i}></span>
        ))}
      </div>

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Expertise</h1>
        <p>Crafting scalable systems, meaningful insights & real-world solutions</p>
      </div>

      {/* BENTO */}
      <div className="bento">

        {/* TECH */}
        <div className="card">
          <h2><FaCode /> Tech Stack</h2>
          <div className="tags">
            <span>Java</span>
            <span>React.js</span>
            <span>Spring Boot</span>
            <span>MySQL</span>
            <span>HTML</span>
            <span>CSS</span>
            <span>JavaScript</span>
            <span>Power BI</span>
          </div>
        </div>

        {/* CODING PROFILES */}
        <div className="card highlight">
          <h2><FaLaptopCode /> Coding Profiles</h2>

          <div className="profiles">
            <a href="https://leetcode.com/yourusername" target="_blank" rel="noreferrer">
              <div>
                <span>LeetCode</span>
                <p>200+ Problems Solved</p>
              </div>
              <FaExternalLinkAlt />
            </a>

            <a href="https://www.hackerrank.com/yourusername" target="_blank" rel="noreferrer">
              <div>
                <span>HackerRank</span>
                <p>5★ Problem Solving</p>
              </div>
              <FaExternalLinkAlt />
            </a>
          </div>
        </div>

        {/* CERTIFICATIONS */}
        <div className="card">
          <h2><FaAward /> Certifications</h2>
          <div className="list">
            <p>✔ Java Programming – NPTEL</p>
            <p>✔ Data Science – NPTEL</p>
            <p>✔ SQL – HackerRank</p>
            <p>✔ Python – SoloLearn</p>
          </div>
        </div>

      </div>

      {/* TIMELINE */}
      <div className="timeline-section">
        <h2>Internship Experience</h2>

        <div className="timeline">

          <div className="item">
            <div className="dot"></div>
            <div className="content">
              <h3>Full Stack Java Intern</h3>
              <h4>Retech Solutions</h4>
              <p>
                Developed a Student Portal using Spring Boot, REST APIs, and MySQL with secure authentication.
              </p>
              <p>
                Improved backend performance through modular architecture and optimized API handling.
              </p>
            </div>
          </div>

          <div className="item">
            <div className="dot"></div>
            <div className="content">
              <h3>Data Analytics Intern</h3>
              <h4>Retech Solutions</h4>
              <p>
                Built Power BI dashboards, performed data cleaning, and generated business insights.
              </p>
              <p>
                Enhanced reporting clarity using structured visualizations and KPI tracking.
              </p>
            </div>
          </div>

        </div>
      </div>

      {/* SOFT SKILLS */}
      <div className="soft-card">
        <h2>Soft Skills</h2>

        <div className="chips">
          <span><FaUsers /> Teamwork</span>
          <span><FaComments /> Communication</span>
          <span><FaLightbulb /> Problem Solving</span>
          <span><FaCogs /> Adaptability</span>
          <span><FaBrain /> Creativity</span>
          <span><FaUsersCog /> Leadership</span>
          <span><FaClock /> Time Management</span>
        </div>
      </div>

      {/* STYLES */}
      <style>{`

        .skills-page{
          min-height:100vh;
          padding:8px 10%;
          font-family:"Poppins",sans-serif;
          background: radial-gradient(circle at top,#0b1220,#050816);
          color:white;
          position:relative;
          overflow:hidden;
        }

        .glow{
          position:absolute;
          width:500px;
          height:500px;
          background:radial-gradient(circle,#38BDF8,transparent);
          top:-150px;
          right:-100px;
          filter:blur(100px);
          opacity:0.2;
        }

        /* PARTICLES */
        .particles span{
          position:absolute;
          width:3px;
          height:3px;
          background:#38BDF8;
          border-radius:50%;
          animation: move 10s linear infinite;
          opacity:0.4;
        }

        .particles span:nth-child(odd){
          animation-duration:12s;
        }

        @keyframes move{
          from{
            transform:translateY(100vh);
          }
          to{
            transform:translateY(-10vh);
          }
        }

        /* random positioning */
        .particles span{
          left: calc(100% * var(--i));
        }

        .header{
          text-align:center;
          margin-bottom:50px;
        }

        .header h1{
          font-size:46px;
          color:#38BDF8;
        }

        .header p{
          color:#94a3b8;
        }

        .bento{
          display:grid;
          grid-template-columns: repeat(3,1fr);
          gap:20px;
        }

        .card{
          background:rgba(255,255,255,0.04);
          border:1px solid rgba(56,189,248,0.2);
          border-radius:16px;
          padding:20px;
          transition:0.3s;
          backdrop-filter:blur(12px);
        }

        .card:hover{
          transform:translateY(-6px);
          box-shadow:0 0 30px rgba(56,189,248,0.2);
        }

        .highlight{
          background:linear-gradient(135deg, rgba(56,189,248,0.15), rgba(56,189,248,0.05));
        }

        h2{
          color:#38BDF8;
          margin-bottom:12px;
          display:flex;
          align-items:center;
          gap:8px;
        }

        .tags{
          display:flex;
          flex-wrap:wrap;
          gap:10px;
        }

        .tags span{
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          padding:6px 12px;
          border-radius:20px;
          font-size:13px;
        }

        .profiles{
          display:flex;
          flex-direction:column;
          gap:12px;
        }

        .profiles a{
          display:flex;
          justify-content:space-between;
          align-items:center;
          padding:12px;
          border-radius:10px;
          text-decoration:none;
          border:1px solid rgba(56,189,248,0.3);
          color:white;
          transition:0.3s;
        }

        .profiles a:hover{
          background:rgba(56,189,248,0.1);
          transform:translateX(5px);
        }

        .timeline-section{
          margin-top:60px;
        }

        .item{
          display:flex;
          gap:15px;
          margin-bottom:25px;
        }

        .dot{
          width:12px;
          height:12px;
          background:#38BDF8;
          border-radius:50%;
        }

        .soft-card{
          margin-top:20px;
          text-align:center;
        }

        .chips{
          display:flex;
          flex-wrap:wrap;
          justify-content:center;
          gap:12px;
          margin-top:15px;
        }

        .chips span{
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          padding:8px 14px;
          border-radius:20px;
        }

        @media(max-width:900px){
          .bento{
            grid-template-columns:1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
